cypress_script:
describe('JavaScript Alerts', () => {
  it('should display JS Alert and accept it', () => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
    cy.contains('button', 'Click for JS Alert').click();
    cy.on('window:alert', (text) => {
      expect(text).to.equal('I am a JS Alert');
    });
    cy.get('#result').should('be.visible');
  });

  it('should display JS Confirm and cancel it', () => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
    cy.contains('button', 'Click for JS Confirm').click();
    cy.on('window:confirm', () => false);
    cy.get('#result').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('JavaScript Alerts', () => {
  test('should display JS Alert and accept it', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
    await page.click('button:text("Click for JS Alert")');
    page.on('dialog', async dialog => {
      expect(dialog.message()).toBe('I am a JS Alert');
      await dialog.accept();
    });
    const result = await page.locator('#result').isVisible();
    expect(result).toBeTruthy();
  });

  test('should display JS Confirm and cancel it', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
    await page.click('button:text("Click for JS Confirm")');
    page.on('dialog', async dialog => {
      await dialog.dismiss();
    });
    const result = await page.locator('#result').isVisible();
    expect(result).toBeTruthy();
  });
});
